// Data access layer. Two very different sources, deliberately:
//
//  - Boundaries and land are
//    static files under public/data/ (generated by scripts/split-data.mjs).
//    They need no query flexibility, so a CDN serves them. Every response is cached in memory for the life of the page
//    and concurrent callers share one in-flight request.
//  - Events: the WHOLE lite set is one static file in a versioned folder
//    (events/v.<version>/all.json, see loadAllLite). The app loads it once and does
//    range, viewport, category/country, drawn-area and title/snippet matching
//    locally, so a default page load makes ZERO API calls.
//  - Free-text search over full leads uses a static index too (lib/textSearch.js),
//    so the app calls no API at all.

import { eventCoords } from "./geo.js";
import { fullBucket } from "./fullBucket.js";
import { decodeGeo } from "./geoCodec.js";
import { BOUNDARIES_VERSION, DATA_VERSION, FULL_BUCKETS } from "./dataVersion.js";

// Pure year helpers live in eventYears.js (testable without the generated
// dataVersion.js); re-exported for the existing importers.
export { DECADE_SIZE, decadeFloor, eventOverlapsRange, eventYearRange } from "./eventYears.js";

const inFlight = new Map(); // url -> Promise<data>, so concurrent callers share one fetch

// One fetch, optionally cancellable (`signal`), time-limited (`timeoutMs`) and
// prioritised (`priority`, the fetch() hint; only the full-record bucket uses it).
// A caller-initiated abort rejects with err.aborted === true and NOT as an
// outage; a timeout, network failure or 5xx is err.outage === true; a 4xx is
// a bad request and says nothing about availability.
// The answer is parsed as JSON, or with `decode(arrayBuffer)` when given (the
// .tbin geometry files, lib/geoCodec.js); a file that does not parse or decode
// fails like a truncated download.
function fetchJSON(url, { timeoutMs, signal, cache, priority, decode } = {}) {
  const controller = timeoutMs || signal ? new AbortController() : null;
  const timer = timeoutMs ? setTimeout(() => controller.abort(), timeoutMs) : null;
  const onAbort = () => controller.abort();
  if (signal) {
    if (signal.aborted) controller.abort();
    else signal.addEventListener("abort", onAbort, { once: true });
  }
  const init = {};
  if (controller) init.signal = controller.signal;
  if (cache) init.cache = cache;
  if (priority) init.priority = priority;
  return fetch(url, controller || cache || priority ? init : undefined)
    .then((res) => {
      if (!res.ok) {
        const err = new Error(`Failed to load ${url}: ${res.status}`);
        err.outage = res.status >= 500;
        throw err;
      }
      // The host answers a missing file with status 404 (wrangler.jsonc
      // not_found_handling "404-page"), handled above. An HTML answer with 200 to
      // a data request (a host or dev server falling back to a page) still means
      // the file is not there: not an outage.
      if (/text\/html/i.test(res.headers.get("content-type") ?? "")) {
        const err = new Error(`Not found: ${url}`);
        err.outage = false;
        throw err;
      }
      return decode ? res.arrayBuffer().then(decode) : res.json();
    })
    .catch((err) => {
      if (signal?.aborted) err.aborted = true;
      else if (err.outage === undefined) err.outage = true;
      throw err;
    })
    .finally(() => {
      clearTimeout(timer);
      signal?.removeEventListener("abort", onAbort);
    });
}

// `check(data)` throws on a file of the wrong shape; it runs before the answer
// counts as a success, so a bad file is evicted like a failed fetch.
function fetchJSONCached(url, { timeoutMs, cache, priority, check, decode } = {}) {
  if (!inFlight.has(url)) {
    const promise = fetchJSON(url, { timeoutMs, cache, priority, decode }).then((data) => {
      check?.(data);
      return data;
    });
    // A failed fetch shouldn't be cached forever - let a later retry try again.
    promise.catch(() => inFlight.delete(url));
    inFlight.set(url, promise);
  }
  return inFlight.get(url);
}

const dataUrl = (relPath) => `${import.meta.env.BASE_URL}data/${relPath}`;

// A geometry file (data/<relPath>.tbin): binary, decoded to the same GeoJSON the
// JSON file held (lib/geoCodec.js, written by scripts/split-data.mjs).
const fetchGeoCached = (relPath, options) => fetchJSONCached(dataUrl(`${relPath}.tbin`), { ...options, decode: decodeGeo });

// Pure physical geography (land/water silhouette) with no time dimension:
// land.tbin for the opening view, land-far.tbin for the rest of the map
// (NEAR_LAND_EXTENT in lib/mapExtent.js).
export function loadLand() {
  return fetchGeoCached("land");
}

// One cell's Natural Earth 1:10m land (scripts/build-land.js, lib/landStore.js).
export function loadLandCell(cell) {
  return fetchGeoCached(`land-cells/${cell}`);
}

export function loadFarLand() {
  return fetchGeoCached("land-far");
}

// A geometry stored apart from the decade chunks: `ref` is "<file>#<index>",
// feature <index> of boundaries/shared/<file>.tbin (split-data.mjs). Members of
// one file share its single download.
function loadSharedGeometry(ref) {
  const [file, index = "0"] = ref.split("#");
  return fetchGeoCached(`boundaries/shared/${file}`).then((fc) => {
    const geometry = fc.features?.[Number(index)]?.geometry;
    if (!geometry) throw new Error(`no shared geometry ${ref}`);
    return geometry;
  });
}

// A decade's FeatureCollection, from the versioned folder
// boundaries/v.<BOUNDARIES_VERSION>/<decade>.tbin (split-data.mjs): the version
// hashes every chunk, and a chunk names its shared files by content hash, so a
// bundle only ever reads chunks of its own build, whose shared files exist. If
// the folder is missing (a 4xx: a page whose bundle is older than the deployed
// data), the current folder is read from boundaries/meta.json (fetched no-cache)
// and used from then on, as loadAllLite does for events.
// A geometry stored apart (`geometry_ref`, see split-data.mjs) is put back here,
// so callers get plain features - except deferred ones (a `minzoom`,
// lib/deferredBoundaries.js), which stay pending until the map asks for them
// with loadDeferredGeometry.
// Concurrent/repeat callers share one load per decade.
const boundaryDecades = new Map(); // decade | "history" -> Promise<FeatureCollection>
let boundariesVersion = BOUNDARIES_VERSION;
// boundaries/v.<version>/<name>.tbin, with the meta.json fallback described above.
function loadBoundaryFile(name) {
  const check = (fc) => {
    if (!Array.isArray(fc?.features)) throw new Error("boundaries file has no features");
  };
  const chunk = (version) => fetchGeoCached(`boundaries/v.${version}/${name}`, { check });
  const tried = boundariesVersion;
  return chunk(tried).catch(async (err) => {
    if (err.outage !== false) throw err;
    const meta = await fetchJSON(dataUrl("boundaries/meta.json"), { cache: "no-cache" });
    if (!meta?.version || meta.version === tried) throw err;
    boundariesVersion = meta.version;
    return chunk(meta.version);
  });
}

// Every boundary feature once (history.tbin, split-data.mjs), for "What was this
// place?" (lib/placeHistory.js). Deferred members stay pending (`geometry_ref`
// and `bbox`): loadDeferredGeometry brings one in when a point is inside its bbox.
export function loadBoundaryHistory() {
  if (!boundaryDecades.has("history")) {
    const promise = loadBoundaryFile("history");
    promise.catch(() => boundaryDecades.delete("history"));
    boundaryDecades.set("history", promise);
  }
  return boundaryDecades.get("history");
}

export function loadBoundaryDecade(decade) {
  if (!boundaryDecades.has(decade)) {
    const promise = loadBoundaryFile(decade)
      .then(async (fc) => {
        const features = await Promise.all(
          fc.features.map(async (f) => {
            if (!f.geometry_ref || f.minzoom != null) return f;
            const { geometry_ref: ref, ...rest } = f;
            return { ...rest, geometry: await loadSharedGeometry(ref) };
          })
        );
        return { ...fc, features };
      });
    promise.catch(() => boundaryDecades.delete(decade));
    boundaryDecades.set(decade, promise);
  }
  return boundaryDecades.get(decade);
}

export function loadDeferredGeometry(ref) {
  return loadSharedGeometry(ref);
}

// Fire-and-forget: warms the cache for a decade without callers waiting on it
// or an error in it propagating anywhere. Used to prefetch neighboring
// boundary decades so crossing a decade boundary while scrubbing the
// timeline rarely has to wait on a fresh request.
export function prefetchBoundaryDecade(decade) {
  loadBoundaryDecade(decade).catch(() => {});
}

// Canonical event shape for everything downstream. Events without usable
// coordinates are KEPT (location_quality "none", coordinates null): they are
// listed and searchable but never get a map marker. Fields are only ever ADDED
// when missing (location_quality, snippet), never rewritten: titles, dates,
// countries and extracts stay exactly as the source gave them.
function normalizeEvent(e) {
  if (!e || !e.id || !e.date_start) return null;
  const out = e;
  if (!eventCoords(out)) {
    out.coordinates = null;
    out.location_quality = "none";
  } else if (!out.location_quality || out.location_quality === "none") {
    out.location_quality = String(out.coordinate_source ?? "").startsWith("country-fallback")
      ? "approximate"
      : "precise";
  }
  if (out.snippet === undefined && typeof out.extract === "string") {
    out.snippet = out.extract.slice(0, 160);
  }
  return out;
}

export function normalizeEvents(events) {
  const out = [];
  for (const e of events) {
    const n = normalizeEvent(e);
    if (n) out.push(n);
  }
  return out;
}

// Every event in the built-in dataset (lite records), regardless of year, in
// ONE static request: events/v.<DATA_VERSION>/all.json. The version in the path
// makes the folder safe to cache immutably. If that folder is missing (a page
// whose bundle is older than the deployed data, or a dev checkout with an old
// split) the current folder and its bucket count are read from events/meta.json
// (fetched no-cache). Either way the folder the list came from is remembered,
// so full records (loadFullLead) are read from the SAME build. Concurrent/repeat
// callers share one load. Each request is time-limited, so a stalled connection
// fails as an outage and useAllEvents' retry starts (all.json is ~90 kB gzipped).
export const ALL_LITE_TIMEOUT_MS = 30000;
let allLitePromise = null;
let source = null; // {version, buckets} of the folder the lite set came from
export function loadAllLite() {
  if (!allLitePromise) {
    const check = (list) => {
      if (!Array.isArray(list)) throw new Error("events file is not an array");
    };
    const load = (version, buckets) =>
      fetchJSONCached(dataUrl(`events/v.${version}/all.json`), { check, timeoutMs: ALL_LITE_TIMEOUT_MS }).then((list) => {
        source = { version, buckets };
        return normalizeEvents(list);
      });
    allLitePromise = load(DATA_VERSION, FULL_BUCKETS).catch(() =>
      fetchJSON(dataUrl("events/meta.json"), { cache: "no-cache", timeoutMs: ALL_LITE_TIMEOUT_MS }).then(({ version, fullBuckets }) => load(version, fullBuckets))
    );
    allLitePromise.catch(() => {
      allLitePromise = null;
    });
  }
  return allLitePromise;
}

// data/selection-funnel.json as published by the data pipeline (About page).
export function loadSelectionFunnel() {
  return fetchJSONCached(dataUrl("selection-funnel.json"));
}

// Summary of our framing review (counts by rating and direction), written by split-data.
export function loadFramingReviewSummary() {
  return fetchJSONCached(dataUrl("framing-review.json"));
}

// The detail record of one event: {extract, extract_retrieved_at, wikipedia_url,
// wikidata_classes, framing_review, ...}. Lives in a small static bucket file
// (events/v.<version>/full/<bucket>.json, see lib/fullBucket.js) that is fetched
// when an event is opened, or just before (prefetchFullLead) - lists never
// download it. Read from the same versioned folder as the lite set, at high
// fetch priority: the open panel waits on it, while the map's geometry for the
// same event downloads alongside. Resolves null if the id is not in its bucket;
// rejects if the file is unreachable.
//
// A page left open across a deploy still points at the folder it loaded, which
// the deploy removed (the host keeps only the current files). When that folder's
// bucket is missing (a 4xx, not an outage), the current folder is read from
// events/meta.json and the record is taken from there: ids are stable, so the
// open page keeps working instead of showing "could not be loaded" until reload.
const bucketUrl = (id, { version, buckets }) => dataUrl(`events/v.${version}/full/${fullBucket(id, buckets)}.json`);
const fetchBucket = (id, from) => fetchJSONCached(bucketUrl(id, from), { priority: "high" });

export async function loadFullLead(id) {
  await loadAllLite();
  const read = async (from) => {
    const bucket = await fetchBucket(id, from);
    return Object.prototype.hasOwnProperty.call(bucket, id) ? bucket[id] : null;
  };
  try {
    return await read(source);
  } catch (err) {
    if (err.outage !== false) throw err;
    const meta = await fetchJSON(dataUrl("events/meta.json"), { cache: "no-cache" });
    if (!meta?.version || meta.version === source.version) throw err;
    source = { version: meta.version, buckets: meta.fullBuckets };
    return read(source);
  }
}

// Fire-and-forget: starts the event's bucket download before it is opened - for
// an event link, in parallel with all.json; later, as a list row or event link
// is pointed at, focused or pressed (lib/warmEvent.js). It reads the folder the
// lite set came from, or before that is known the folder this bundle names
// (where the lite set comes from too, unless that folder is gone). loadFullLead
// then shares the cached request; a failed one is dropped from the cache, so
// loadFullLead tries again, with its meta.json fallback.
export function prefetchFullLead(id) {
  fetchBucket(id, source ?? { version: DATA_VERSION, buckets: FULL_BUCKETS }).catch(() => {});
}
